-- rule odd_quantity (mode_outlier): parameterized; p1 bigint, p2 numeric, p3 numeric, p4 numeric
WITH g AS (SELECT t."child_id" AS grp, count(*) AS n_rows, count(DISTINCT t."parent_id") AS n_distinct FROM "sxc_rules"."bom_line" t WHERE t."child_id" IS NOT NULL GROUP BY t."child_id"), f AS (SELECT t."child_id" AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_rules"."bom_line" t WHERE t."child_id" IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY t."child_id", t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE g.n_distinct >= CAST(:p1 AS bigint) AND f.n_val * CAST(:p2 AS numeric) >= CAST(:p3 AS numeric) * g.n_rows AND f.val > 0) SELECT t."parent_id", t."child_id", t."qty_per", m.mode_value AS "mode", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN m ON m.grp = t."child_id" WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(:p4 AS numeric) * m.mode_value OR CAST(:p4 AS numeric) * t."qty_per" <= m.mode_value) GROUP BY t."parent_id", t."child_id", t."qty_per", m.mode_value;

-- rule odd_quantity: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_odd_quantity" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST, r."child_id" COLLATE "C" NULLS FIRST, r."qty_per" NULLS FIRST, r."mode" NULLS FIRST, r."n" NULLS FIRST) AS ord FROM (WITH g AS (SELECT t."child_id" AS grp, count(*) AS n_rows, count(DISTINCT t."parent_id") AS n_distinct FROM "sxc_rules"."bom_line" t WHERE t."child_id" IS NOT NULL GROUP BY t."child_id"), f AS (SELECT t."child_id" AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_rules"."bom_line" t WHERE t."child_id" IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY t."child_id", t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE g.n_distinct >= CAST(E'3' AS bigint) AND f.n_val * CAST(E'4' AS numeric) >= CAST(E'3' AS numeric) * g.n_rows AND f.val > 0) SELECT t."parent_id", t."child_id", t."qty_per", m.mode_value AS "mode", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN m ON m.grp = t."child_id" WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(E'20' AS numeric) * m.mode_value OR CAST(E'20' AS numeric) * t."qty_per" <= m.mode_value) GROUP BY t."parent_id", t."child_id", t."qty_per", m.mode_value) r;

-- example odd_quantity[0]: parameterized; 22 parameters
WITH "sxc_ex_bom_line"("child_id", "qty_per", "parent_id") AS (VALUES (CAST(:p1 AS text), CAST(:p2 AS numeric(18,6)), CAST(:p3 AS text)), (CAST(:p4 AS text), CAST(:p5 AS numeric(18,6)), CAST(:p6 AS text)), (CAST(:p7 AS text), CAST(:p8 AS numeric(18,6)), CAST(:p9 AS text)), (CAST(:p10 AS text), CAST(:p11 AS numeric(18,6)), CAST(:p12 AS text)), (CAST(:p13 AS text), CAST(:p14 AS numeric(18,6)), CAST(:p15 AS text)), (CAST(:p16 AS text), CAST(:p17 AS numeric(18,6)), CAST(:p18 AS text))) SELECT * FROM (WITH g AS (SELECT t."child_id" AS grp, count(*) AS n_rows, count(DISTINCT t."parent_id") AS n_distinct FROM "sxc_ex_bom_line" t WHERE t."child_id" IS NOT NULL GROUP BY t."child_id"), f AS (SELECT t."child_id" AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_ex_bom_line" t WHERE t."child_id" IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY t."child_id", t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE g.n_distinct >= CAST(:p19 AS bigint) AND f.n_val * CAST(:p20 AS numeric) >= CAST(:p21 AS numeric) * g.n_rows AND f.val > 0) SELECT t."parent_id", t."child_id", t."qty_per", m.mode_value AS "mode", count(*) AS "n" FROM "sxc_ex_bom_line" t JOIN m ON m.grp = t."child_id" WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(:p22 AS numeric) * m.mode_value OR CAST(:p22 AS numeric) * t."qty_per" <= m.mode_value) GROUP BY t."parent_id", t."child_id", t."qty_per", m.mode_value) r;
